[asy]

dot((0,0));
label("1",(0,-1.5));

dot((3,0));
dot((4,0));
dot((3,1));
label("3",(3.5,-1.5));

dot((7,0));
dot((8,0));
dot((9,0));
dot((7,1));
dot((7,2));
dot((8,1));
label("6",(8,-1.5));

dot((12,0));
dot((13,0));
dot((14,0));
dot((15,0));
dot((12,1));
dot((13,1));
dot((14,1));
dot((12,2));
dot((13,2));
dot((12,3));
label("10",(13.5,-1.5));

[/asy]

If each of the variables represents a different digit, what is the value of $a+b+c+d$?

[asy]
label("$a$",(1,0),E);
label("$b$",(2,0),E);
label("$c$",(3,0),E);
label("$d$",(1,-1),E);
label("$c$",(2,-1),E);
label("$a$",(3,-1),E);
label("+",(-2,-1),E);
draw((-2.1,-1.4)--(4.1,-1.4),linewidth(0.5));
label("1",(0,-2),E);
for (int i =0; i<3; ++i) {
label("0",(1+i,-2),E);
}
[/asy]

